        "É utilizado apenas o maior rosto de cada fotografia. Sempre que possível, use fotografias nítidas de uma só pessoa. São incluídos os ficheiros JPG, JPEG, PNG e WebP diretamente nesta pasta; as subpastas são ignoradas.",
        "На каждой фотографии используется только самое крупное лицо. По возможности выбирайте чёткие фотографии одного человека. Учитываются файлы JPG, JPEG, PNG и WebP непосредственно в этой папке; вложенные папки игнорируются.",
